const test = require('node:test');
const assert = require('node:assert/strict');
const { containsValue } = require('../src/value-membership.cjs');

test("SameValueZero recognizes NaN without coercing types", () => {
  assert.equal(containsValue([7, NaN, 12], NaN), true);
  assert.equal(containsValue([0], -0), true);
  assert.equal(containsValue([7], '7'), false);
  assert.equal(containsValue([], undefined), false);
});

test("empty slots behave as undefined entries", () => {
  const sparse = ['oak', , 'pine'];
  assert.equal(containsValue(sparse, undefined), true);
  assert.equal(containsValue(sparse, undefined, 2), false);
  assert.equal(1 in sparse, false);
});

test("negative starting positions count from the end then search forward", () => {
  assert.equal(containsValue(['oak', 'pine', 'elm'], 'oak', -2), false);
  assert.equal(containsValue(['oak', 'pine', 'elm'], 'elm', -2), true);
  assert.equal(containsValue(['oak'], 'oak', -99), true);
  assert.equal(containsValue(['oak'], 'oak', 1), false);
});

